// @FIGURE_CODE_BEGIN
// title → HTML label, black serif
// joint embedding disk → billboard CircleGeometry(0.62) orange fill with black circular Line outline
// top arrows → thick cylinder shafts + cone heads, black
// encoder side rules → vertical black cylinder lines with rotated HTML labels
// embedding planes → horizontal transparent PlaneGeometry rectangles in XZ with dark Line outlines and faint grid LineSegments
// process arrows → vertical thick black cylinder+cone arrows beside each branch
// process boxes → billboard rounded ShapeGeometry white fill + black Line outline with monospace HTML labels
// image markers → small horizontal CircleGeometry / PlaneGeometry / triangle BufferGeometry colored with thin dark outlines
// image trajectories → dashed Line geometry, same concept color, transparent
// text labels → HTML labels anchored just above each text plane
// text trajectories → dashed gray Line geometry, transparent
// active layer highlights → golden enlarged rectangle Line loops around active image/text planes
// hover proxies → invisible SphereGeometry hit targets on markers and text labels

const layerYs = [-4, -2, 0, 2, 4];
const leftX = -1.9;
const rightX = 1.9;
const planeW = 2.35;
const planeD = 1.35;
const hw = planeW / 2;
const hd = planeD / 2;

const states = ['input', 'vitTransformer1', 'vitTransformer2', 'vitTransformer3', 'vitTransformer4', 'jointEmbedding'];
const stateNames = {
  input: 'input embeddings',
  vitTransformer1: 'ViT / transformer block 1',
  vitTransformer2: 'ViT / transformer block 2',
  vitTransformer3: 'ViT / transformer block 3',
  vitTransformer4: 'ViT / transformer block 4',
  jointEmbedding: 'joint embedding space'
};

let activeState = 'input';
let activeLayer = 0;
let branchMode = 'Both branches';
let hoverConcept = null;

const branchStruct = { image: [], text: [] };
const branchLabels = { image: [], text: [] };
const conceptMarkers = [];
const conceptTextLabels = [];
const imagePathRecords = [];
const textPathRecords = [];
const hoverTargets = [];
const allPlanes = { image: [], text: [] };

function basicMat(color, opacity = 1) {
  const m = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: opacity >= 0.95
  });
  m.userData.baseOpacity = opacity;
  return m;
}

function lineMat(color, opacity = 1, dashed = false) {
  const m = dashed
    ? new THREE.LineDashedMaterial({ color, transparent: true, opacity, dashSize: 0.12, gapSize: 0.075 })
    : new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  m.userData.baseOpacity = opacity;
  return m;
}

function tagObject(obj, branch) {
  branchStruct[branch].push(obj);
  obj.traverse(o => {
    const mats = Array.isArray(o.material) ? o.material : (o.material ? [o.material] : []);
    mats.forEach(m => {
      if (m.userData.baseOpacity == null) m.userData.baseOpacity = m.opacity;
      m.transparent = true;
    });
  });
  return obj;
}

function setMaterialOpacity(mat, opacity) {
  mat.opacity = Math.max(0, Math.min(1, opacity));
  mat.transparent = mat.opacity < 0.999;
  mat.needsUpdate = true;
}

function setObjectOpacity(obj, factor) {
  obj.traverse(o => {
    const mats = Array.isArray(o.material) ? o.material : (o.material ? [o.material] : []);
    mats.forEach(m => setMaterialOpacity(m, (m.userData.baseOpacity ?? 1) * factor));
  });
}

function cylinderBetween(start, end, radius, mat) {
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  const geom = new THREE.CylinderGeometry(radius, radius, len, 12);
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  scene.add(mesh);
  return mesh;
}

function makeArrow(startArr, endArr, branch = null, opts = {}) {
  const start = new THREE.Vector3(...startArr);
  const end = new THREE.Vector3(...endArr);
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  const headLen = opts.headLen ?? 0.24;
  const shaftRadius = opts.shaftRadius ?? 0.025;
  const headRadius = opts.headRadius ?? 0.085;
  const unit = dir.clone().normalize();
  const shaftEnd = end.clone().addScaledVector(unit, -headLen);
  const group = new THREE.Group();

  const shaft = cylinderBetween(start, shaftEnd, shaftRadius, basicMat(0x000000, 1));
  scene.remove(shaft);
  group.add(shaft);

  const cone = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLen, 20), basicMat(0x000000, 1));
  cone.position.copy(shaftEnd).addScaledVector(unit, headLen / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), unit);
  group.add(cone);

  scene.add(group);
  if (branch) tagObject(group, branch);
  return group;
}

function createPlane(cx, y, branch) {
  const group = new THREE.Group();
  group.position.set(cx, y, 0);

  const fill = new THREE.Mesh(new THREE.PlaneGeometry(planeW, planeD), basicMat(0xffffff, 0.08));
  fill.rotation.x = -Math.PI / 2;
  group.add(fill);

  const outlinePts = [
    new THREE.Vector3(-hw, 0.015, -hd), new THREE.Vector3(hw, 0.015, -hd),
    new THREE.Vector3(hw, 0.015, hd), new THREE.Vector3(-hw, 0.015, hd),
    new THREE.Vector3(-hw, 0.015, -hd)
  ];
  const outline = new THREE.Line(new THREE.BufferGeometry().setFromPoints(outlinePts), lineMat(0x3b3b3b, 0.95));
  group.add(outline);

  const gridPositions = [];
  [-0.33, 0.33].forEach(u => {
    gridPositions.push(u * hw, 0.012, -hd, u * hw, 0.012, hd);
  });
  [-0.35, 0.35].forEach(v => {
    gridPositions.push(-hw, 0.012, v * hd, hw, 0.012, v * hd);
  });
  gridPositions.push(-hw, 0.012, -hd, hw, 0.012, hd);
  gridPositions.push(-hw, 0.012, hd, hw, 0.012, -hd);
  const gridGeom = new THREE.BufferGeometry();
  gridGeom.setAttribute('position', new THREE.Float32BufferAttribute(gridPositions, 3));
  const grid = new THREE.LineSegments(gridGeom, lineMat(0xd8d8d8, 0.35));
  group.add(grid);

  scene.add(group);
  tagObject(group, branch);
  allPlanes[branch].push(group);
  return group;
}

function createHighlight(cx) {
  const pts = [
    new THREE.Vector3(-hw - 0.08, 0.075, -hd - 0.08),
    new THREE.Vector3(hw + 0.08, 0.075, -hd - 0.08),
    new THREE.Vector3(hw + 0.08, 0.075, hd + 0.08),
    new THREE.Vector3(-hw - 0.08, 0.075, hd + 0.08),
    new THREE.Vector3(-hw - 0.08, 0.075, -hd - 0.08)
  ];
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat(0xffb000, 0.95));
  line.position.set(cx, layerYs[0], 0);
  scene.add(line);
  return line;
}

function roundedShape(w, h, r) {
  const x = -w / 2, y = -h / 2;
  const s = new THREE.Shape();
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

function makeBillboardGroup(group) {
  group.traverse(child => {
    if (child.isMesh || child.isLine) {
      child.onBeforeRender = (_, __, cam) => {
        group.quaternion.copy(cam.quaternion);
      };
    }
  });
}

function createRoundedBox(x, y, z, w, h, text, branch) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const shape = roundedShape(w, h, 0.11);
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shape), basicMat(0xffffff, 0.98));
  const borderPts2 = shape.getPoints(48).map(p => new THREE.Vector3(p.x, p.y, 0.012));
  borderPts2.push(borderPts2[0].clone());
  const border = new THREE.Line(new THREE.BufferGeometry().setFromPoints(borderPts2), lineMat(0x000000, 1));
  group.add(fill, border);
  scene.add(group);
  makeBillboardGroup(group);
  tagObject(group, branch);
  return group;
}

function createBillboardDisk() {
  const group = new THREE.Group();
  group.position.set(0, 5.05, 0);
  const fill = new THREE.Mesh(new THREE.CircleGeometry(0.62, 72), basicMat(0xffa77f, 1));
  const pts = [];
  for (let i = 0; i <= 96; i++) {
    const a = (i / 96) * Math.PI * 2;
    pts.push(new THREE.Vector3(Math.cos(a) * 0.62, Math.sin(a) * 0.62, 0.015));
  }
  const border = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat(0x000000, 1));
  group.add(fill, border);
  scene.add(group);
  makeBillboardGroup(group);
  registerInteractive(group, {
    title: 'Joint embedding space',
    tooltip: 'Shared CLIP embedding space',
    body: 'The two encoders send their final image and text representations into one shared space, where matching visual and language concepts are encouraged to align.'
  });
  return group;
}

function planePoint(cx, layer, uv, lift = 0.055) {
  return new THREE.Vector3(cx + uv[0] * hw, layerYs[layer] + lift, uv[1] * hd);
}

function makeTriangleGeometry(size) {
  const h = size * 0.95;
  const verts = new Float32Array([
    0, 0.002, h * 0.65,
    -size * 0.58, 0.002, -h * 0.45,
    size * 0.58, 0.002, -h * 0.45
  ]);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  return geom;
}

function makeMarker(concept, shape, color, pos, layer) {
  const group = new THREE.Group();
  group.position.copy(pos);
  const size = 0.14;
  let mesh;
  if (shape === 'circle') {
    mesh = new THREE.Mesh(new THREE.CircleGeometry(size * 0.48, 24), basicMat(color, 0.92));
    mesh.rotation.x = -Math.PI / 2;
  } else if (shape === 'square') {
    mesh = new THREE.Mesh(new THREE.PlaneGeometry(size * 0.72, size * 0.72), basicMat(color, 0.92));
    mesh.rotation.x = -Math.PI / 2;
  } else {
    mesh = new THREE.Mesh(makeTriangleGeometry(size), basicMat(color, 0.92));
  }
  group.add(mesh);

  const outlinePts = [];
  const r = size * 0.5;
  const n = shape === 'triangle' ? 3 : 28;
  for (let i = 0; i <= n; i++) {
    const a = shape === 'triangle' ? Math.PI / 2 + (i % 3) * Math.PI * 2 / 3 : i * Math.PI * 2 / n;
    outlinePts.push(new THREE.Vector3(Math.cos(a) * r, 0.006, Math.sin(a) * r));
  }
  const outline = new THREE.Line(new THREE.BufferGeometry().setFromPoints(outlinePts), lineMat(0x333333, 0.55));
  group.add(outline);

  group.userData.concept = concept;
  group.userData.layer = layer;
  group.userData.branch = 'image';
  scene.add(group);
  conceptMarkers.push({ concept, layer, object: group });
  hoverTargets.push(group);
  registerInteractive(group, {
    title: concept,
    tooltip: `Follow “${concept}”`,
    body: `This colored image marker is the visual counterpart of the text label “${concept}”. Hovering highlights its image and text trajectories through the encoder stacks.`
  });
  return group;
}

function makeDashedLine(points, color, opacity, branch, concept, layer, collection) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = lineMat(color, opacity, true);
  const line = new THREE.Line(geom, mat);
  line.computeLineDistances();
  line.userData.concept = concept;
  line.userData.layer = layer;
  scene.add(line);
  collection.push({ concept, layer, object: line, material: mat, baseOpacity: opacity, branch });
  return line;
}

