function basicMat(color, opacity = 1) {
  const m = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: opacity >= 0.95
  });
  m.userData.baseOpacity = opacity;
  return m;
}

function lineMat(color, opacity = 1, dashed = false) {
  const m = dashed
    ? new THREE.LineDashedMaterial({ color, transparent: true, opacity, dashSize: 0.12, gapSize: 0.075 })
    : new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  m.userData.baseOpacity = opacity;
  return m;
}

function tagObject(obj, branch) {
  branchStruct[branch].push(obj);
  obj.traverse(o => {
    const mats = Array.isArray(o.material) ? o.material : (o.material ? [o.material] : []);
    mats.forEach(m => {
      if (m.userData.baseOpacity == null) m.userData.baseOpacity = m.opacity;
      m.transparent = true;
    });
  });
  return obj;
}

function setMaterialOpacity(mat, opacity) {
  mat.opacity = Math.max(0, Math.min(1, opacity));
  mat.transparent = mat.opacity < 0.999;
  mat.needsUpdate = true;
}

function setObjectOpacity(obj, factor) {
  obj.traverse(o => {
    const mats = Array.isArray(o.material) ? o.material : (o.material ? [o.material] : []);
    mats.forEach(m => setMaterialOpacity(m, (m.userData.baseOpacity ?? 1) * factor));
  });
}

function cylinderBetween(start, end, radius, mat) {
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  const geom = new THREE.CylinderGeometry(radius, radius, len, 12);
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  scene.add(mesh);
  return mesh;
}

function makeArrow(startArr, endArr, branch = null, opts = {}) {
  const start = new THREE.Vector3(...startArr);
  const end = new THREE.Vector3(...endArr);
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  const headLen = opts.headLen ?? 0.24;
  const shaftRadius = opts.shaftRadius ?? 0.025;
  const headRadius = opts.headRadius ?? 0.085;
  const unit = dir.clone().normalize();
  const shaftEnd = end.clone().addScaledVector(unit, -headLen);
  const group = new THREE.Group();

  const shaft = cylinderBetween(start, shaftEnd, shaftRadius, basicMat(0x000000, 1));
  scene.remove(shaft);
  group.add(shaft);

  const cone = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLen, 20), basicMat(0x000000, 1));
  cone.position.copy(shaftEnd).addScaledVector(unit, headLen / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), unit);
  group.add(cone);

  scene.add(group);
