Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="clipLayerStep" type="button">Step upward through CLIP layers</button>
<div id="clipLayerReadout" style="font:12px/1.35 sans-serif;color:#222;">Layer: input embeddings</div>
<label>
  Branch view
  <select id="branchVisibility">
    <option>Both branches</option>
    <option>Image branch only</option>
    <option>Text branch only</option>
  </select>
</label>
<div id="clipNarration" style="font:11px/1.35 sans-serif;color:#333;margin-top:4px;">
  Hover a colored marker or text label to follow one concept through both encoders.
</div>
<div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:4px;">
  <button id="demo0" type="button">1</button>
  <button id="demo1" type="button">2</button>
  <button id="demo2" type="button">3</button>
  <button id="demo3" type="button">4</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// title → HTML label, black serif, centered above disk
// joint embedding disk → billboard CircleGeometry black back disk + orange front disk
// top arrows → thick black cylinder shafts + cone heads from top planes into disk
// encoder side rules → tall black CylinderGeometry rules with large rotated HTML labels
// embedding planes → horizontal transparent PlaneGeometry rectangles in XZ, thick cylinder edge outlines, faint grid LineSegments
// process arrows → large vertical black cylinder+cone arrows outside each branch
// process boxes → billboard rounded ShapeGeometry black border + white fill with monospace HTML labels
// image markers → small horizontal circle/square/triangle meshes in concept colors with dark outline lines
// image trajectories → dashed colored Line segments between corresponding markers
// text labels → staggered HTML labels anchored just above each text plane with translucent white backing
// text trajectories → dashed gray Line segments between corresponding word-label anchors
// active layer highlights → pale-gold thick rectangular tube frames around active image/text planes
// hover proxies → invisible SphereGeometry targets at every marker/text anchor

const layerYs = [-4, -2, 0, 2, 4];
const leftX = -2.18;
const rightX = 2.18;
const planeW = 2.42;
const planeD = 1.40;
const hw = planeW / 2;
const hd = planeD / 2;

const states = ['input', 'vitTransformer1', 'vitTransformer2', 'vitTransformer3', 'vitTransformer4', 'jointEmbedding'];
const stateNames = {
  input: 'input embeddings',
  vitTransformer1: 'ViT / transformer block 1',
  vitTransformer2: 'ViT / transformer block 2',
  vitTransformer3: 'ViT / transformer block 3',
  vitTransformer4: 'ViT / transformer block 4',
  jointEmbedding: 'joint embedding space'
};

let activeState = 'input';
let activeLayer = 0;
let branchMode = 'Both branches';
let hoverConcept = null;

const branchStruct = { image: [], text: [] };
const branchLabels = { image: [], text: [] };
const conceptMarkers = [];
const conceptTextLabels = [];
const imagePathRecords = [];
const textPathRecords = [];
const hoverTargets = [];
const activeHighlights = [];

function basicMat(color, opacity = 1, depthWrite = true) {
  const m = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: depthWrite && opacity >= 0.95
  });
  m.userData.baseOpacity = opacity;
  return m;
}

function lineMat(color, opacity = 1, dashed = false) {
  const m = dashed
    ? new THREE.LineDashedMaterial({ color, transparent: true, opacity, dashSize: 0.12, gapSize: 0.075 })
    : new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  m.userData.baseOpacity = opacity;
  return m;
}

function setMaterialOpacity(mat, opacity) {
  mat.opacity = Math.max(0, Math.min(1, opacity));
  mat.transparent = mat.opacity < 0.999;
  mat.needsUpdate = true;
}

function tagObject(obj, branch) {
  branchStruct[branch].push(obj);
  obj.traverse(o => {
    const mats = Array.isArray(o.material) ? o.material : (o.material ? [o.material] : []);
    mats.forEach(m => {
      if (m.userData.baseOpacity == null) m.userData.baseOpacity = m.opacity ?? 1;
      m.transparent = true;
    });
  });
  return obj;
}

function setObjectOpacity(obj, factor) {
  obj.traverse(o => {
    const mats = Array.isArray(o.material) ? o.material : (o.material ? [o.material] : []);
    mats.forEach(m => setMaterialOpacity(m, (m.userData.baseOpacity ?? 1) * factor));
  });
}

function cylinderBetween(start, end, radius, mat, addToScene = true) {
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = Math.max(dir.length(), 1e-5);
  const geom = new THREE.CylinderGeometry(radius, radius, len, 18);
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  if (addToScene) scene.add(mesh);
  return mesh;
}

function makeArrow(startArr, endArr, branch = null, opts = {}) {
  const start = new THREE.Vector3(...startArr);
  const end = new THREE.Vector3(...endArr);
  const dir = new THREE.Vector3().subVectors(end, start);
  const headLen = opts.headLen ?? 0.30;
  const shaftRadius = opts.shaftRadius ?? 0.036;
  const headRadius = opts.headRadius ?? 0.12;
  const unit = dir.clone().normalize();
  const shaftEnd = end.clone().addScaledVector(unit, -headLen);
  const group = new THREE.Group();

  group.add(cylinderBetween(start, shaftEnd, shaftRadius, basicMat(0x000000, 1), false));

  const cone = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLen, 28), basicMat(0x000000, 1));
  cone.position.copy(shaftEnd).addScaledVector(unit, headLen / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), unit);
  group.add(cone);

  scene.add(group);
  if (branch) tagObject(group, branch);
  return group;
}

function createPlane(cx, y, branch) {
  const group = new THREE.Group();
  group.position.set(cx, y, 0);

  const fill = new THREE.Mesh(new THREE.PlaneGeometry(planeW, planeD), basicMat(0xffffff, 0.10, false));
  fill.rotation.x = -Math.PI / 2;
  group.add(fill);

  const edgeMat = basicMat(0x3a3a3a, 0.98);
  const edgeR = 0.014;
  [
    [new THREE.Vector3(-hw, 0.018, -hd), new THREE.Vector3(hw, 0.018, -hd)],
    [new THREE.Vector3(hw, 0.018, -hd), new THREE.Vector3(hw, 0.018, hd)],
    [new THREE.Vector3(hw, 0.018, hd), new THREE.Vector3(-hw, 0.018, hd)],
    [new THREE.Vector3(-hw, 0.018, hd), new THREE.Vector3(-hw, 0.018, -hd)]
  ].forEach(([a, b]) => group.add(cylinderBetween(a, b, edgeR, edgeMat, false)));

  const gridPositions = [];
  [-0.35, 0.35].forEach(u => gridPositions.push(u * hw, 0.014, -hd, u * hw, 0.014, hd));
  [-0.36, 0.36].forEach(v => gridPositions.push(-hw, 0.014, v * hd, hw, 0.014, v * hd));
  gridPositions.push(-hw, 0.014, -hd, hw, 0.014, hd);
  gridPositions.push(-hw, 0.014, hd, hw, 0.014, -hd);
  const gridGeom = new THREE.BufferGeometry();
  gridGeom.setAttribute('position', new THREE.Float32BufferAttribute(gridPositions, 3));
  group.add(new THREE.LineSegments(gridGeom, lineMat(0xd8d8d8, 0.35)));

  scene.add(group);
  tagObject(group, branch);
  return group;
}

function createHighlight(cx, branch) {
  const group = new THREE.Group();
  const pad = 0.09;
  const mat = basicMat(0xd7ac45, 0.34);
  const y = 0.075;
  const r = 0.020;
  const corners = [
    new THREE.Vector3(-hw - pad, y, -hd - pad),
    new THREE.Vector3(hw + pad, y, -hd - pad),
    new THREE.Vector3(hw + pad, y, hd + pad),
    new THREE.Vector3(-hw - pad, y, hd + pad)
  ];
  for (let i = 0; i < 4; i++) group.add(cylinderBetween(corners[i], corners[(i + 1) % 4], r, mat, false));
  group.position.set(cx, layerYs[0], 0);
  group.userData.branch = branch;
  scene.add(group);
  activeHighlights.push(group);
  return group;
}

function roundedShape(w, h, r) {
  const x = -w / 2, y = -h / 2;
  const s = new THREE.Shape();
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

function makeBillboardGroup(group) {
  group.onBeforeRender = (_, __, cam) => group.quaternion.copy(cam.quaternion);
  group.traverse(child => {
    child.onBeforeRender = (_, __, cam) => group.quaternion.copy(cam.quaternion);
  });
}

function createRoundedBox(x, y, z, w, h, branch) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const outer = new THREE.Mesh(new THREE.ShapeGeometry(roundedShape(w, h, 0.12)), basicMat(0x000000, 1));
  const inner = new THREE.Mesh(new THREE.ShapeGeometry(roundedShape(w - 0.075, h - 0.075, 0.10)), basicMat(0xffffff, 1));
  inner.position.z = 0.018;
  group.add(outer, inner);
  scene.add(group);
  makeBillboardGroup(group);
  tagObject(group, branch);
  return group;
}

function createBillboardDisk() {
  const group = new THREE.Group();
  group.position.set(0, 5.08, 0);
  const back = new THREE.Mesh(new THREE.CircleGeometry(0.67, 96), basicMat(0x000000, 1));
  const fill = new THREE.Mesh(new THREE.CircleGeometry(0.58, 96), basicMat(0xffa77f, 1));
  fill.position.z = 0.018;
  group.add(back, fill);
  scene.add(group);
  makeBillboardGroup(group);
  registerInteractive(group, {
    title: 'Joint embedding space',
    tooltip: 'Shared CLIP embedding space',
    body: 'The final image and text embeddings are projected into one shared space, so nearby locations can mean matching visual and language concepts.'
  });
  return group;
}

function planePoint(cx, layer, uv, lift = 0.06) {
  return new THREE.Vector3(cx + uv[0] * hw, layerYs[layer] + lift, uv[1] * hd);
}

function makeTriangleGeometry(size) {
  const h = size * 1.06;
  const verts = new Float32Array([
    0, 0.003, h * 0.65,
    -size * 0.58, 0.003, -h * 0.45,
    size * 0.58, 0.003, -h * 0.45
  ]);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  return geom;
}

function markerOutline(shape, size) {
  const pts = [];
  if (shape === 'square') {
    const s = size * 0.42;
    pts.push(new THREE.Vector3(-s, 0.008, -s), new THREE.Vector3(s, 0.008, -s), new THREE.Vector3(s, 0.008, s), new THREE.Vector3(-s, 0.008, s), new THREE.Vector3(-s, 0.008, -s));
  } else if (shape === 'triangle') {
    const r = size * 0.63;
    for (let i = 0; i <= 3; i++) {
      const a = Math.PI / 2 + (i % 3) * Math.PI * 2 / 3;
      pts.push(new THREE.Vector3(Math.cos(a) * r, 0.008, Math.sin(a) * r));
    }
  } else {
    const r = size * 0.54;
    for (let i = 0; i <= 36; i++) {
      const a = i * Math.PI * 2 / 36;
      pts.push(new THREE.Vector3(Math.cos(a) * r, 0.008, Math.sin(a) * r));
    }
  }
  return new THREE.BufferGeometry().setFromPoints(pts);
}

function makeMarker(concept, shape, color, pos, layer) {
  const group = new THREE.Group();
  group.position.copy(pos);
  const size = 0.145;
  let mesh;
  if (shape === 'circle') {
    mesh = new THREE.Mesh(new THREE.CircleGeometry(size * 0.54, 32), basicMat(color, 0.96));
    mesh.rotation.x = -Math.PI / 2;
  } else if (shape === 'square') {
    mesh = new THREE.Mesh(new THREE.PlaneGeometry(size * 0.82, size * 0.82), basicMat(color, 0.96));
    mesh.rotation.x = -Math.PI / 2;
  } else {
    mesh = new THREE.Mesh(makeTriangleGeometry(size), basicMat(color, 0.96));
  }
  group.add(mesh);
  group.add(new THREE.Line(markerOutline(shape, size), lineMat(0x333333, 0.78)));
  group.userData.concept = concept;
  group.userData.layer = layer;
  group.userData.branch = 'image';
  scene.add(group);
  conceptMarkers.push({ concept, layer, object: group });
  hoverTargets.push(group);
  registerInteractive(group, {
    title: concept,
    tooltip: `Follow “${concept}”`,
    body: `The colored ${shape} is the image-side representation of “${concept}”. Its dashed path can be compared with the same-named text path.`
  });
  return group;
}

function makeDashedLine(points, color, opacity, branch, concept, layer, collection) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = lineMat(color, opacity, true);
  const line = new THREE.Line(geom, mat);
  line.computeLineDistances();
  line.userData.concept = concept;
  line.userData.layer = layer;
  scene.add(line);
  collection.push({ concept, layer, object: line, material: mat, baseOpacity: opacity, branch });
  return line;
}

const concepts = [
  { name: 'red circle', shape: 'circle', color: 0xff7f9b },
  { name: 'pink circle', shape: 'circle', color: 0xff9ec2 },
  { name: 'purple circle', shape: 'circle', color: 0xc2a8ff },
  { name: 'orange circle', shape: 'circle', color: 0xf3b55a },
  { name: 'blue circle', shape: 'circle', color: 0x73c7e6 },
  { name: 'green square', shape: 'square', color: 0x58c99c },
  { name: 'pink square', shape: 'square', color: 0xff70d8 },
  { name: 'blue square', shape: 'square', color: 0x84d8f0 },
  { name: 'blue triangle', shape: 'triangle', color: 0x62bfdc },
  { name: 'purple triangle', shape: 'triangle', color: 0xb8a1ff }
];

const imageUV = {
  'red circle': [[0.65,-0.45],[0.05,-0.25],[-0.20,0.05],[-0.50,0.15],[-0.55,0.35]],
  'pink circle': [[0.80,-0.50],[0.10,-0.20],[-0.25,0.00],[-0.60,0.20],[-0.65,0.30]],
  'purple circle': [[0.45,-0.35],[-0.15,-0.10],[-0.05,0.18],[-0.40,0.35],[-0.25,0.45]],
  'orange circle': [[0.55,-0.42],[-0.05,-0.15],[-0.10,0.10],[-0.35,0.25],[-0.45,0.40]],
  'blue circle': [[0.25,-0.30],[0.25,-0.05],[0.15,0.25],[-0.10,0.35],[-0.20,0.50]],
  'green square': [[0.10,-0.25],[-0.35,-0.05],[-0.45,0.15],[-0.65,0.25],[-0.35,0.55]],
  'pink square': [[0.85,-0.55],[0.35,-0.12],[-0.55,0.10],[-0.70,0.35],[-0.15,0.62]],
  'blue square': [[0.70,-0.38],[0.55,-0.05],[-0.35,0.20],[-0.45,0.40],[-0.05,0.58]],
  'blue triangle': [[0.35,-0.52],[0.65,0.10],[0.45,0.35],[0.05,0.50],[0.75,0.35]],
  'purple triangle': [[0.05,-0.32],[-0.05,0.25],[-0.35,0.35],[-0.10,0.45],[0.35,0.55]]
};

const textUV = {
  'red circle': [[-0.45,-0.55],[-0.55,-0.20],[-0.50,0.02],[-0.35,0.22],[-0.55,0.35]],
  'pink circle': [[-0.25,-0.50],[-0.42,-0.15],[-0.38,0.05],[-0.45,0.20],[-0.65,0.30]],
  'purple circle': [[-0.10,-0.45],[-0.58,0.00],[-0.65,0.12],[-0.55,0.25],[-0.25,0.45]],
  'orange circle': [[0.55,-0.52],[-0.20,-0.20],[-0.30,0.02],[-0.25,0.18],[-0.45,0.40]],
  'blue circle': [[0.20,-0.42],[-0.05,-0.05],[-0.10,0.18],[0.00,0.35],[-0.20,0.50]],
  'green square': [[-0.35,-0.30],[-0.15,0.05],[-0.30,0.25],[-0.50,0.30],[-0.35,0.55]],
  'pink square': [[-0.05,-0.35],[-0.32,0.10],[-0.42,0.18],[-0.40,0.35],[-0.15,0.62]],
  'blue square': [[0.05,-0.25],[-0.25,0.15],[-0.32,0.22],[-0.30,0.42],[-0.05,0.58]],
  'blue triangle': [[0.65,-0.10],[0.80,0.10],[0.55,0.30],[0.45,0.42],[0.75,0.35]],
  'purple triangle': [[0.10,-0.20],[0.00,0.18],[-0.10,0.30],[-0.05,0.45],[0.35,0.55]]
};

for (const y of layerYs) {
  createPlane(leftX, y, 'image');
  createPlane(rightX, y, 'text');
}

const imageHighlight = createHighlight(leftX, 'image');
const textHighlight = createHighlight(rightX, 'text');

createBillboardDisk();
makeArrow([-1.46, 4.72, 0], [-0.55, 5.00, 0], 'image', { shaftRadius: 0.040, headRadius: 0.135, headLen: 0.30 });
makeArrow([1.46, 4.72, 0], [0.55, 5.00, 0], 'text', { shaftRadius: 0.040, headRadius: 0.135, headLen: 0.30 });

const leftRuleX = -5.05;
const rightRuleX = 5.05;
const leftBoxX = -4.36;
const rightBoxX = 4.36;

tagObject(cylinderBetween(new THREE.Vector3(leftRuleX, -4.68, 0), new THREE.Vector3(leftRuleX, 4.42, 0), 0.014, basicMat(0x000000, 1)), 'image');
tagObject(cylinderBetween(new THREE.Vector3(rightRuleX, -4.68, 0), new THREE.Vector3(rightRuleX, 4.42, 0), 0.014, basicMat(0x000000, 1)), 'text');

[-3, -1, 1, 3].forEach(y => {
  makeArrow([leftBoxX, y - 0.78, 0], [leftBoxX, y + 0.82, 0], 'image', { shaftRadius: 0.035, headRadius: 0.125, headLen: 0.30 });
  makeArrow([rightBoxX, y - 0.78, 0], [rightBoxX, y + 0.82, 0], 'text', { shaftRadius: 0.035, headRadius: 0.125, headLen: 0.30 });
  createRoundedBox(leftBoxX, y, 0.05, 1.48, 0.42, 'image');
  createRoundedBox(rightBoxX, y, 0.05, 2.06, 0.42, 'text');
});

for (const c of concepts) {
  const imagePoints = [];
  const textPoints = [];
  for (let l = 0; l < 5; l++) {
    const ip = planePoint(leftX, l, imageUV[c.name][l], 0.080);
    imagePoints.push(ip);
    makeMarker(c.name, c.shape, c.color, ip, l);

    const tp = planePoint(rightX, l, textUV[c.name][l], 0.122);
    textPoints.push(tp);
    const proxy = new THREE.Mesh(
      new THREE.SphereGeometry(0.22, 12, 8),
      new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
    );
    proxy.position.copy(tp);
    proxy.userData.concept = c.name;
    proxy.userData.branch = 'text';
    proxy.userData.layer = l;
    scene.add(proxy);
    hoverTargets.push(proxy);
    registerInteractive(proxy, {
      title: c.name,
      tooltip: `Follow “${c.name}”`,
      body: `This word label is the text-side representation of “${c.name}”. The dashed gray path shows its movement through transformer layers.`
    });
  }
  for (let l = 0; l < 4; l++) {
    makeDashedLine([imagePoints[l], imagePoints[l + 1]], c.color, 0.48, 'image', c.name, l, imagePathRecords);
    makeDashedLine([textPoints[l], textPoints[l + 1]], 0x555555, 0.56, 'text', c.name, l, textPathRecords);
  }
}

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.88,
  target: [0, 0.12, 0],
  distanceScale: 1.05
});

const titleLabel = addLabel('Joint embedding space', new THREE.Vector3(0, 5.87, 0), { fontSize: '27px', color: '#000' });
titleLabel.div.style.fontFamily = 'Georgia, Times, serif';

const imageEnc = addLabel('<span style="writing-mode:vertical-rl;transform:rotate(180deg);display:inline-block;">Image encoder</span>', new THREE.Vector3(leftRuleX - 0.22, -0.12, 0), { fontSize: '25px', color: '#000' });
imageEnc.div.style.fontFamily = 'Georgia, Times, serif';
branchLabels.image.push({ entry: imageEnc, base: 1 });

const textEnc = addLabel('<span style="writing-mode:vertical-rl;transform:rotate(180deg);display:inline-block;">Text encoder</span>', new THREE.Vector3(rightRuleX + 0.22, -0.12, 0), { fontSize: '25px', color: '#000' });
textEnc.div.style.fontFamily = 'Georgia, Times, serif';
branchLabels.text.push({ entry: textEnc, base: 1 });

[-3, -1, 1, 3].forEach(y => {
  const l = addLabel('ViT block x3', new THREE.Vector3(leftBoxX, y, 0.16), { fontSize: '17px', color: '#000' });
  l.div.style.fontFamily = 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';
  branchLabels.image.push({ entry: l, base: 1 });

  const r = addLabel('transformer block x3', new THREE.Vector3(rightBoxX, y, 0.16), { fontSize: '15px', color: '#000' });
  r.div.style.fontFamily = 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';
  branchLabels.text.push({ entry: r, base: 1 });
});

const labelOffsets = [
  [-26, -16], [-6, -10], [18, -16], [30, -5], [-34, 5],
  [10, 12], [-28, 17], [22, 18], [38, 10], [-10, 26]
];

for (const c of concepts) {
  const ci = concepts.findIndex(item => item.name === c.name);
  for (let l = 0; l < 5; l++) {
    const p = planePoint(rightX, l, textUV[c.name][l], 0.225);
    p.x += ((ci % 3) - 1) * 0.035 + (l % 2 ? 0.018 : -0.018);
    p.z += (Math.floor(ci / 3) - 1) * 0.026 + (l - 2) * 0.010;
    const base = labelOffsets[ci];
    const layerStagger = [(l - 2) * 5, ((ci + l) % 2 ? 4 : -4)];
    const label = addLabel(c.name, p, {
      fontSize: l === 4 ? '11px' : '10px',
      color: '#111',
      offset: [base[0] + layerStagger[0], base[1] + layerStagger[1]],
      background: 'rgba(255,255,255,0.62)'
    });
    label.div.style.fontFamily = 'Arial, Helvetica, sans-serif';
    label.div.style.lineHeight = '1';
    label.div.style.padding = '0 2px';
    conceptTextLabels.push({ concept: c.name, layer: l, entry: label });
  }
}

const clipBtn = document.getElementById('clipLayerStep');
const readout = document.getElementById('clipLayerReadout');
const branchSelect = document.getElementById('branchVisibility');
const narration = document.getElementById('clipNarration');

function branchFactor(branch) {
  if (branchMode === 'Both branches') return 1;
  if (branchMode === 'Image branch only') return branch === 'image' ? 1 : 0.13;
  if (branchMode === 'Text branch only') return branch === 'text' ? 1 : 0.13;
  return 1;
}

function stateToLayer(s) {
  if (s === 'jointEmbedding') return 4;
  return Math.max(0, states.indexOf(s));
}

function updateStyles() {
  activeLayer = stateToLayer(activeState);

  for (const obj of branchStruct.image) setObjectOpacity(obj, branchFactor('image'));
  for (const obj of branchStruct.text) setObjectOpacity(obj, branchFactor('text'));

  branchLabels.image.forEach(l => { l.entry.div.style.opacity = String(l.base * branchFactor('image')); });
  branchLabels.text.forEach(l => { l.entry.div.style.opacity = String(l.base * branchFactor('text')); });

  imageHighlight.position.set(leftX, layerYs[activeLayer], 0);
  textHighlight.position.set(rightX, layerYs[activeLayer], 0);
  setObjectOpacity(imageHighlight, branchFactor('image') * 0.95);
  setObjectOpacity(textHighlight, branchFactor('text') * 0.95);

  conceptMarkers.forEach(rec => {
    const same = !hoverConcept || rec.concept === hoverConcept;
    const layerWeight = rec.layer === activeLayer ? 1 : 0.58;
    const hoverWeight = same ? (hoverConcept ? 1.20 : 1) : 0.18;
    setObjectOpacity(rec.object, branchFactor('image') * layerWeight * hoverWeight);
    const s = rec.layer === activeLayer ? 1.16 : 1.0;
    rec.object.scale.setScalar(hoverConcept === rec.concept ? 1.28 : s);
  });

  conceptTextLabels.forEach(rec => {
    const same = !hoverConcept || rec.concept === hoverConcept;
    const layerWeight = rec.layer === activeLayer ? 1 : 0.44;
    const hoverWeight = same ? (hoverConcept ? 1.0 : 1) : 0.18;
    rec.entry.div.style.opacity = String(branchFactor('text') * layerWeight * hoverWeight);
    rec.entry.div.style.fontWeight = (hoverConcept === rec.concept || rec.layer === activeLayer) ? '700' : '400';
    rec.entry.div.style.background = rec.layer === activeLayer
      ? 'rgba(255,255,255,0.86)'
      : 'rgba(255,255,255,0.50)';
  });

  imagePathRecords.forEach(rec => {
    const same = !hoverConcept || rec.concept === hoverConcept;
    const layerEmphasis = (rec.layer === activeLayer || rec.layer === activeLayer - 1) ? 1.25 : 0.70;
    const op = rec.baseOpacity * branchFactor('image') * layerEmphasis * (same ? (hoverConcept ? 1.85 : 1) : 0.18);
    setMaterialOpacity(rec.material, Math.min(1, op));
  });

  textPathRecords.forEach(rec => {
    const same = !hoverConcept || rec.concept === hoverConcept;
    const layerEmphasis = (rec.layer === activeLayer || rec.layer === activeLayer - 1) ? 1.20 : 0.64;
    const op = rec.baseOpacity * branchFactor('text') * layerEmphasis * (same ? (hoverConcept ? 1.65 : 1) : 0.18);
    setMaterialOpacity(rec.material, Math.min(1, op));
  });

  clipBtn.textContent = `Step upward through CLIP layers: ${stateNames[activeState]}`;
  readout.textContent = `Layer: ${stateNames[activeState]}`;
}

clipBtn.addEventListener('click', () => {
  const i = states.indexOf(activeState);
  activeState = states[(i + 1) % states.length];
  updateStyles();
});

branchSelect.addEventListener('change', () => {
  branchMode = branchSelect.value;
  updateStyles();
});

const demoSteps = [
  {
    title: 'Input embeddings',
    narration: 'At the bottom, the image branch begins with colored geometric markers while the text branch begins with word labels. Matching concepts exist in both columns but are not yet arranged in a common layout.',
    state: { clipLayerStep: 'input', branchVisibility: 'Both branches' }
  },
  {
    title: 'Encoder blocks reshape each modality',
    narration: 'Stepping upward highlights successive ViT and transformer block outputs. The dashed paths show that each modality reorganizes its own points through several intermediate embedding planes.',
    state: { clipLayerStep: 'vitTransformer2', branchVisibility: 'Both branches' }
  },
  {
    title: 'Compare one branch at a time',
    narration: 'Switching to one branch fades the other, making the internal image-only or text-only transformation easier to read without losing the overall column structure.',
    state: { clipLayerStep: 'vitTransformer3', branchVisibility: 'Image branch only' }
  },
  {
    title: 'Joint embedding alignment',
    narration: 'At the top, both arrows enter the same orange joint embedding disk. Hovering a marker or label brightens its paired trajectory in both branches, emphasizing cross-modal alignment.',
    state: { clipLayerStep: 'jointEmbedding', branchVisibility: 'Both branches' }
  }
];

window.goToStep = function goToStep(i) {
  const step = demoSteps[Math.max(0, Math.min(demoSteps.length - 1, i | 0))];
  activeState = step.state.clipLayerStep;
  branchMode = step.state.branchVisibility;
  branchSelect.value = branchMode;
  narration.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  updateStyles();
};

for (let i = 0; i < 4; i++) {
  document.getElementById(`demo${i}`).addEventListener('click', () => window.goToStep(i));
}

const hoverRay = new THREE.Raycaster();
const hoverPointer = new THREE.Vector2();

function findConceptUnderPointer(event) {
  const rect = canvas.getBoundingClientRect();
  hoverPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  hoverPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  hoverRay.setFromCamera(hoverPointer, camera);
  const hits = hoverRay.intersectObjects(hoverTargets, true);
  for (const hit of hits) {
    let obj = hit.object;
    while (obj) {
      if (obj.userData && obj.userData.concept) return obj.userData.concept;
      obj = obj.parent;
    }
  }
  return null;
}

canvas.addEventListener('pointermove', (event) => {
  const c = findConceptUnderPointer(event);
  if (c !== hoverConcept) {
    hoverConcept = c;
    updateStyles();
  }
});

canvas.addEventListener('pointerleave', () => {
  hoverConcept = null;
  updateStyles();
});

window.goToStep(0);
